window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[278]={"id":"278","numero":278,"titre":"Ictère","objectifs":[{"id":"278-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un ictère du nouveau-né","contenu":"<p>L'<span class=\"kw-clinique\">ictère</span> du nouveau-né est une <span class=\"kw-def\">coloration jaune de la peau et des conjonctives</span>, qui s'étend dans le sens <strong><span class=\"kw-clinique\">céphalo-caudal</span></strong> — du visage vers les extrémités. Il est <strong>fréquent</strong> (<span class=\"kw-chiffre\">2 nouveau-nés / 3</span>), en majorité à <span class=\"kw-bio\">bilirubine libre</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<strong><span class=\"kw-clinique\">atteinte des plantes des pieds</span></strong> témoigne de l'<span class=\"kw-alerte\">intensité</span> de l'ictère — repère clinique de sévérité à vérifier systématiquement.</div>\n\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> — la production de <span class=\"kw-bio\">bilirubine</span> du nouveau-né est <strong><span class=\"kw-chiffre\">2 à 3 fois supérieure</span></strong> à celle de l'adulte. Trois mécanismes s'additionnent :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Hémolyse physiologique</span></strong> survenant à la naissance.</li>\n        <li><strong><span class=\"kw-def\">Immaturité hépatique</span></strong> — maturation de la <span class=\"kw-bio\">bilirubine glucuronyl-transférase</span> retardée de quelques jours.</li>\n        <li><strong><span class=\"kw-def\">Augmentation du cycle entéro-hépatique</span></strong> — l'absence de <span class=\"kw-clinique\">flore bactérienne</span> intestinale favorise la <span class=\"kw-bio\">réabsorption de la bilirubine</span>.</li>\n      </ul>\n\n      <h4>Ictères bénins — caractéristiques comparées</h4>\n      <table>\n        <thead>\n          <tr><th>Critère</th><th><span class=\"kw-etio\">Ictère simple</span> (physiologique)</th><th><span class=\"kw-etio\">Ictère au lait de mère</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence / mécanisme</strong></td>\n            <td>Le plus fréquent (jusqu'à la moitié des nouveau-nés) ; défaut physiologique de <span class=\"kw-bio\">glucuroconjugaison</span> lié à l'adaptation néonatale</td>\n            <td>Nouveau-nés à terme avec <strong>lactation maternelle importante</strong> dès les premiers jours, inhibant la <span class=\"kw-bio\">glucuroconjugaison</span></td>\n          </tr>\n          <tr>\n            <td><strong>Début</strong></td>\n            <td><span class=\"kw-chiffre\">&gt; 24 h</span> de vie</td>\n            <td>Vers <span class=\"kw-chiffre\">J5-J6</span> (peut faire suite à l'ictère simple)</td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>Isolé, normal</td>\n            <td>Isolé, normal</td>\n          </tr>\n          <tr>\n            <td><strong>Bilirubine transcutanée</strong></td>\n            <td><span class=\"kw-bio\">BTc &lt; 75ᵉ percentile</span> du nomogramme</td>\n            <td><span class=\"kw-bio\">BTc &lt; 75ᵉ percentile</span> du nomogramme</td>\n          </tr>\n          <tr>\n            <td><strong>Évolution</strong></td>\n            <td>Décroissance à partir de <span class=\"kw-chiffre\">J5-J6</span>, disparition avant <span class=\"kw-chiffre\">J10</span></td>\n            <td>Persistance pendant <span class=\"kw-chiffre\">4 à 6 semaines</span></td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>Aucune — abstention thérapeutique</td>\n            <td>Aucune — <strong>ne pas interrompre l'allaitement</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Qualification de l'hyperbilirubinémie</h4>\n      <table>\n        <thead><tr><th>Qualificatif</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Pathologique</span></strong></td><td>Bilirubinémie totale <span class=\"kw-chiffre\">≥ 95ᵉ percentile</span> du nomogramme. L'hyperbilirubinémie physiologique peut devenir pathologique en cas de perturbation de l'adaptation (<span class=\"kw-etio\">prématurité</span>, retard d'alimentation…) ou de circonstances pathologiques (<span class=\"kw-etio\">incompatibilité de groupe sanguin</span>, <span class=\"kw-etio\">allo-immunisation</span>, <span class=\"kw-etio\">maladie hémolytique</span>…).</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Sévère</span></strong></td><td>BT <span class=\"kw-chiffre\">&gt; 340 µmol/L</span> dans les <span class=\"kw-chiffre\">96 premières heures</span> de vie, ou <span class=\"kw-chiffre\">&gt; 420 µmol/L</span> après 96 h chez le nouveau-né à terme. <span class=\"kw-alerte\">Risque neurologique</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Précoce</span></strong></td><td>Survenue au cours des <span class=\"kw-chiffre\">24 premières heures</span> de vie.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs de risque d'hyperbilirubinémie pathologique</h4>\n      <table>\n        <thead><tr><th>Anamnestiques</th><th>Cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>Âge gestationnel <span class=\"kw-chiffre\">&lt; 38 SA</span></li>\n                <li>Situation d'<span class=\"kw-bio\">incompatibilité ABO</span></li>\n                <li><span class=\"kw-bio\">RAI maternelles positives</span></li>\n                <li><span class=\"kw-etio\">Hémolyse familiale</span></li>\n                <li>Antécédents d'ictère traité dans la fratrie</li>\n                <li>Origine géographique des parents / grands-parents : <span class=\"kw-clinique\">Asie</span>, <span class=\"kw-clinique\">Afrique</span>, <span class=\"kw-clinique\">Antilles</span></li>\n                <li>Survenue de l'ictère <span class=\"kw-chiffre\">&lt; 24 h</span> de vie</li>\n                <li>Durée de l'ictère <span class=\"kw-chiffre\">&gt; 10 jours</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Perte pondérale</span> <span class=\"kw-chiffre\">&lt; 8 %</span></li>\n                <li><span class=\"kw-clinique\">Bosse séro-sanguine</span>, <span class=\"kw-clinique\">ecchymoses</span>, <span class=\"kw-clinique\">hématomes</span></li>\n                <li>Intensité de l'ictère jusqu'à la <strong>plante des pieds</strong></li>\n                <li><span class=\"kw-clinique\">Examen neurologique anormal</span></li>\n                <li><span class=\"kw-etio\">Anémie hémolytique</span> (pâleur, hépato-splénomégalie)</li>\n                <li><span class=\"kw-clinique\">Cholestase</span> (urines foncées, selles décolorées — échelle colorimétrique des selles, hépatomégalie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Indications d'un bilan sanguin de confirmation</h4>\n      <ul>\n        <li>Bilirubine transcutanée <span class=\"kw-chiffre\">≥ 75ᵉ percentile</span> du nomogramme ;</li>\n        <li>Facteurs de risque d'<span class=\"kw-bio\">hyperbilirubinémie libre</span> prolongée ou récidivante ;</li>\n        <li>Signes <span class=\"kw-clinique\">anamnestiques</span> ou cliniques d'ictère pathologique ;</li>\n        <li>Ictère prolongé <strong>au-delà de la 1ʳᵉ semaine</strong> chez le nouveau-né à terme, ou <strong>de la 2ᵉ semaine</strong> de vie.</li>\n      </ul>","frequence":3},{"id":"278-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les situations urgentes devant un ictère du nouveau-né","contenu":"<p>Trois situations imposent une prise en charge urgente devant un <span class=\"kw-clinique\">ictère</span> néonatal.</p>\n      <p><strong>1. L'<span class=\"kw-clinique\">ictère</span> nucléaire</strong> (<span class=\"kw-etio\">encéphalopathie hyperbilirubinémique</span>) — complication redoutée, liée à la toxicité de la <strong><span class=\"kw-bio\">bilirubine libre</span></strong> sur le cerveau néonatal, particulièrement vulnérable. <span class=\"kw-def\">Facteurs de risque</span> :</p>\n      <ul>\n        <li><strong>Prématurité</strong> et <strong>jeûne</strong>.</li>\n        <li><span class=\"kw-ttt\">Médicaments fixés à l'albumine</span> (type <span class=\"kw-ttt\">aminosides</span>) — ils déplacent la <span class=\"kw-bio\">bilirubine</span> de l'<span class=\"kw-bio\">albumine</span>.</li>\n        <li><span class=\"kw-alerte\">Déshydratation</span>, hypo-osmolarité, <span class=\"kw-bio\">hypoalbuminémie</span>.</li>\n        <li><span class=\"kw-alerte\">Infection</span>, acidose, hypoxie, <span class=\"kw-clinique\">hypothermie</span>, hypoglycémie.</li>\n      </ul>\n      <p><strong>2 et 3. Urgences liées à la cause</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Atrésie des voies biliaires</span></strong> — <span class=\"kw-clinique\">ictère</span> à <span class=\"kw-bio\">bilirubine conjuguée</span> ; la précocité de la <span class=\"kw-ttt\">chirurgie</span> conditionne le <span class=\"kw-def\">pronostic</span>.</li>\n        <li><strong><span class=\"kw-etio\">Allo-immunisation érythrocytaire materno-fœtale</span></strong> — <span class=\"kw-clinique\">ictère</span> à <span class=\"kw-bio\">bilirubine libre</span>, risque hémolytique.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> L'<span class=\"kw-alerte\">ictère nucléaire</span> laisse des séquelles neurologiques <span class=\"kw-alerte\">irréversibles</span> par <span class=\"kw-clinique\">lésion</span> des noyaux gris centraux et du tronc cérébral : <span class=\"kw-clinique\">syndrome extrapyramidal</span>, <span class=\"kw-clinique\">choréoathétose</span>, <span class=\"kw-clinique\">surdité de perception</span>, <span class=\"kw-clinique\">paralysie oculomotrice</span>, <span class=\"kw-clinique\">déficit intellectuel</span>.</div>","frequence":1},{"id":"278-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la stratégie diagnostique devant un ictère du nouveau-né","contenu":"<p>Objectif central de l'item. La démarche vise à distinguer un <span class=\"kw-clinique\">ictère</span> <strong>bénin</strong> d'un <span class=\"kw-clinique\">ictère</span> <span class=\"kw-alerte\">pathologique</span>, puis à en préciser la cause selon le type de <span class=\"kw-bio\">bilirubine prédominante</span>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Démarche</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Repérer un <span class=\"kw-clinique\">ictère</span> pathologique ou de sévérité</strong></td>\n            <td>\n              <strong>Caractéristiques :</strong> délai de survenue <span class=\"kw-chiffre\">&lt; 24 h de vie</span> ; durée <span class=\"kw-chiffre\">&gt; 10 jours</span> ; intensité atteignant <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">plantes des pieds</span> ;<br>\n              <strong><span class=\"kw-def\">Terrain</span> :</strong> âge gestationnel <span class=\"kw-chiffre\">&lt; 38 SA</span> ; ATCD d'<span class=\"kw-clinique\">ictère</span> traité dans la fratrie ; incompatibilité <span class=\"kw-bio\">ABO</span> ou <span class=\"kw-bio\">RAI maternelles positives</span> ; origine géographique Asie, Afrique, Antilles ;<br>\n              <strong>Examen :</strong> perte pondérale <span class=\"kw-chiffre\">&gt; 8 %</span> ; signes d'<span class=\"kw-alerte\">hémolyse</span> (anémie, hépato-<span class=\"kw-clinique\">splénomégalie</span>) ou de <span class=\"kw-alerte\">cholestase</span> (selles décolorées, urines foncées)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-def\">Dépistage</span> systématique en maternité</strong></td>\n            <td><span class=\"kw-bio\">Bilirubinomètre transcutané</span> appliqué sur le <span class=\"kw-clinique\">front</span> et le <span class=\"kw-clinique\">sternum</span>, mesuré <span class=\"kw-chiffre\">≥ 1 fois par jour</span>. Sortie autorisée si la <span class=\"kw-bio\">BTc</span> reste <span class=\"kw-chiffre\">&lt; 75ᵉ percentile</span> des courbes de référence</td>\n          </tr>\n          <tr>\n            <td><strong>3. Confirmation diagnostique</strong></td>\n            <td>Dosage de la <span class=\"kw-bio\">bilirubinémie totale</span> (avec calcul de la <span class=\"kw-bio\">bilirubine</span> libre) et de la <span class=\"kw-bio\">bilirubine conjuguée</span>.<br>\n              <strong>Indications :</strong> <span class=\"kw-bio\">BTc ≥ 75ᵉ percentile</span> ; signes orientant vers un <span class=\"kw-clinique\">ictère</span> pathologique ; <span class=\"kw-clinique\">ictère</span> persistant <span class=\"kw-chiffre\">&gt; J7</span> chez le nouveau-né à terme ou <span class=\"kw-chiffre\">&gt; J14</span> chez le prématuré</td>\n          </tr>\n          <tr>\n            <td><strong>4. Bilan paraclinique orienté</strong></td>\n            <td>\n              <strong>Systématique — écarter une cause infectieuse :</strong> <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-bio\">ECBU</span> (si <span class=\"kw-clinique\">ictère</span> <span class=\"kw-chiffre\">&gt; J7</span>), données bactériologiques maternelles ;<br>\n              <strong>Si <span class=\"kw-bio\">bilirubine</span> libre :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">réticulocytes</span>, groupe sanguin enfant + mère, <span class=\"kw-bio\">Coombs direct</span> ;<br>\n              <strong>Si <span class=\"kw-bio\">bilirubine conjuguée</span> :</strong> <span class=\"kw-bio\">bilan hépatique</span> (<span class=\"kw-bio\">PAL</span>, <span class=\"kw-bio\">γGT</span>, transaminases, <span class=\"kw-bio\">hémostase</span>) + <span class=\"kw-imagerie\">échographie abdominale</span> ;<br>\n              <strong>Selon le contexte :</strong> <span class=\"kw-bio\">G6PD</span>, <span class=\"kw-bio\">pyruvate kinase</span>, <span class=\"kw-bio\">TSH</span> et <span class=\"kw-bio\">T4</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Chez le nouveau-né, l'<span class=\"kw-bio\">haptoglobine</span> n'a aucun intérêt diagnostique : elle est constitutivement basse du fait de l'<span class=\"kw-def\">hémolyse physiologique</span>. À l'<span class=\"kw-imagerie\">échographie</span>, l'<span class=\"kw-radio\">absence de vésicule biliaire</span> oriente vers une atrésie des voies biliaires.</div>\n      <p><strong>Causes d'<span class=\"kw-clinique\">ictère</span> néonatal selon le type de <span class=\"kw-bio\">bilirubine</span></strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Libre — ictères bénins</strong></td><td><span class=\"kw-etio\">Ictère simple</span> (physiologique) ; <span class=\"kw-etio\">ictère au lait de mère</span></td></tr>\n          <tr><td><strong>Libre — hémolyse</strong></td><td><span class=\"kw-etio\">Allo-immunisations érythrocytaires materno-fœtales</span> (ABO, Rhésus) ; hémolyses constitutionnelles : maladie de Minkowski-Chauffard, déficit en G6PD, déficit en pyruvate kinase</td></tr>\n          <tr><td><strong>Libre — sans hémolyse</strong></td><td><span class=\"kw-etio\">Infections materno-fœtales</span> ; <span class=\"kw-etio\">hypothyroïdie</span> ; <span class=\"kw-etio\">syndrome de Crigler-Najjar</span></td></tr>\n          <tr><td><strong>Conjuguée — <span class=\"kw-clinique\">cholestase</span> intra-hépatique</strong></td><td><span class=\"kw-etio\">Infections post-natales</span> (<span class=\"kw-etio\">E. coli</span>) ; infections virales (<span class=\"kw-etio\">CMV</span>, EBV, Échovirus)</td></tr>\n          <tr><td><strong>Conjuguée — <span class=\"kw-clinique\">cholestase</span> extra-hépatique</strong></td><td><strong><span class=\"kw-etio\">Atrésie des voies biliaires</span></strong> ; autres anomalies des voies biliaires</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 243 — <span class=\"kw-def\">Hypothyroïdie</span> · 245 — Insuffisance surrénale</em></p>","frequence":8},{"id":"278-4","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’un ictère du nouveau-né","contenu":"<p>La prise en charge dépend du type de <span class=\"kw-bio\">bilirubine</span> et du caractère bénin ou pathologique de l'<span class=\"kw-clinique\">ictère</span>.</p>\n      <p><strong><span class=\"kw-ttt\">Photothérapie</span></strong> — traitement de base :</p>\n      <ul>\n        <li><strong>Indication</strong> — <span class=\"kw-clinique\">ictère</span> à <span class=\"kw-bio\">bilirubine libre</span> dont l'intensité fait craindre un <span class=\"kw-alerte\">ictère nucléaire</span>.</li>\n        <li><strong>Principe</strong> — exposition à la <span class=\"kw-ttt\">lumière bleue</span>, qui convertit la <span class=\"kw-bio\">bilirubine</span> en produits de dégradation hydrosolubles, éliminables par le rein.</li>\n        <li><strong>Prévention des complications</strong> — protection des gonades par la couche ; <span class=\"kw-clinique\">port de lunettes</span> pour <span class=\"kw-clinique\">les</span> yeux ; <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-clinique\">température</span> et <span class=\"kw-clinique\">cardiorespiratoire</span> ; alimentation toutes les <span class=\"kw-chiffre\">3 heures</span>.</li>\n      </ul>\n      <p><strong>Autres mesures thérapeutiques</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Exsanguino-transfusion</span></strong> — indication rare, devant un <span class=\"kw-clinique\">ictère</span> à <span class=\"kw-bio\">bilirubine</span> libre <span class=\"kw-alerte\">très sévère</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Perfusions d'albumine</span></strong> — chez l'enfant vulnérable (hypotrophie, prématurité, acidose, <span class=\"kw-clinique\">déshydratation</span>).</li>\n        <li><strong><span class=\"kw-ttt\">Immunoglobulines polyvalentes IV</span></strong> — allo-immunisation materno-fœtale Rhésus ou ABO documentée, en adjuvant de la <span class=\"kw-ttt\">photothérapie</span> intensive.</li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Ictère</span> à <span class=\"kw-bio\">bilirubine conjuguée</span></strong> — devant une <span class=\"kw-clinique\">cholestase</span>, notamment une <span class=\"kw-etio\">atrésie des voies biliaires</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Vitamine K parentérale</span></strong> (IV ou IM) — dès la constatation des signes de <span class=\"kw-clinique\">cholestase</span>, en raison du <span class=\"kw-alerte\">risque hémorragique</span>.</li>\n        <li><strong>Avis chirurgical urgent</strong> — la <span class=\"kw-clinique\">précocité de l'intervention</span> conditionne le <span class=\"kw-def\">pronostic</span> (<span class=\"kw-alerte\">risque de cirrhose</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'<span class=\"kw-etio\">ictère simple</span> et l'<span class=\"kw-etio\">ictère au lait de mère</span> relèvent de l'<strong>abstention thérapeutique</strong>. Ne jamais interrompre l'<span class=\"kw-ci\">allaitement</span> maternel : <span class=\"kw-clinique\">les</span> bénéfices priment sur la coloration ictérique prolongée.</div>","frequence":3},{"id":"278-5","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un ictère de l’adulte","contenu":"<p>L'<span class=\"kw-clinique\">ictère</span> de l'adulte est une <span class=\"kw-def\">coloration jaune à bronze, généralisée, des téguments et des conjonctives</span>, secondaire à une augmentation de la <span class=\"kw-bio\">bilirubinémie</span> — conjuguée ou non conjuguée.</p>\n      <p><strong>Seuils de bilirubinémie</strong> :</p>\n      <table >\n        <thead><tr><th>Bilirubinémie</th><th>Traduction clinique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 20 µmol/L</span></td><td>Valeur normale</td></tr>\n          <tr><td><span class=\"kw-chiffre\">20 à 40 µmol/L</span></td><td>Élévation non détectable à l'inspection</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 40 à 50 µmol/L</span></td><td><span class=\"kw-clinique\">Ictère</span> cliniquement visible</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Deux formes de <span class=\"kw-bio\">bilirubine</span></strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Bilirubine non-conjuguée (libre)</span></strong> — <span class=\"kw-bio\">insoluble</span>, presque totalement liée à l'<span class=\"kw-bio\">albumine</span> ; ne franchit pas la barrière glomérulaire, donc <strong>absente des urines</strong>.</li>\n        <li><strong><span class=\"kw-bio\">Bilirubine conjuguée</span></strong> — <span class=\"kw-bio\">soluble</span> ; passe librement le glomérule, donc <strong>retrouvée dans <span class=\"kw-clinique\">les</span> urines</strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-clinique\">ictère</span> est dit <strong>à <span class=\"kw-bio\">bilirubine</span> non-conjuguée</strong> si celle-ci représente <span class=\"kw-chiffre\">&gt; 70 %</span> de la bilirubinémie totale ; il est <strong>mixte ou conjugué</strong> dans <span class=\"kw-clinique\">les</span> autres cas.</div>","frequence":1},{"id":"278-6","rang":"B","rubrique":"Définition","titre":"Connaître la définition du syndrome de Gilbert","contenu":"<p>Le <span class=\"kw-clinique\">syndrome de Gilbert</span> est une anomalie <strong>très fréquente</strong> (<span class=\"kw-chiffre\">5 à 10 %</span> de la population), de transmission <span class=\"kw-def\">autosomique récessive</span>.</p>\n      <ul>\n        <li><strong>Cause</strong> — mutation du <strong><span class=\"kw-def\">promoteur</span></strong> de la <span class=\"kw-bio\">bilirubine</span> glucuronyl-transférase, entraînant un <span class=\"kw-alerte\">déficit partiel</span> de l'enzyme (<span class=\"kw-chiffre\">- 20 à 30 %</span>).</li>\n        <li><strong>Biologie</strong> — hyperbilirubinémie <span class=\"kw-bio\">non-conjuguée</span> modérée, toujours <span class=\"kw-chiffre\">&lt; 80 µmol/L</span>, <span class=\"kw-bio\">fluctuante</span> ; tests hépatiques rigoureusement normaux ; pas d'anémie ni de réticulocytose.</li>\n        <li><strong>Fluctuations</strong> — bilirubinémie augmentée par le <span class=\"kw-clinique\">jeûne</span>, la <span class=\"kw-clinique\">fatigue</span> et <span class=\"kw-clinique\">les</span> infections intercurrentes ; diminuée par les <span class=\"kw-ttt\">inducteurs enzymatiques</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-clinique\">syndrome de Gilbert</span> <strong>n'est pas une maladie</strong> : la mutation est nécessaire mais non suffisante à l'expression du syndrome.</div>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <span class=\"kw-clinique\">syndrome de Gilbert</span> majore la <span class=\"kw-alerte\">toxicité de l'irinotécan</span>, <span class=\"kw-ttt\">chimiothérapie</span> éliminée par glucuroconjugaison.</div>","frequence":0},{"id":"278-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies de l’ictère de l’adulte","contenu":"<p>Trois grands mécanismes, distingués par le type de <span class=\"kw-bio\">bilirubine</span> prédominant.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Non-conjuguée — excès de production</strong></td><td><span class=\"kw-etio\">Hyperhémolyse</span> (toutes causes d'hémolyse) ; <span class=\"kw-etio\">dysérythropoïèse</span></td></tr>\n          <tr><td><strong>Non-conjuguée — défaut de conjugaison</strong></td><td><span class=\"kw-etio\">Syndrome de Gilbert</span> ; <span class=\"kw-etio\">syndrome de Crigler-Najjar</span></td></tr>\n          <tr><td><strong>Conjuguée — <span class=\"kw-clinique\">cholestase</span>, obstacle sur la VBP</strong></td><td><span class=\"kw-etio\">Lithiase de la VBP</span> ; <span class=\"kw-etio\">cholangiocarcinome</span> ; <span class=\"kw-etio\">cancer de la tête du pancréas</span> ; <span class=\"kw-clinique\">adénopathie</span> comprimant la VBP ; sténose post-opératoire ; <span class=\"kw-etio\">pancréatite chronique</span> calcifiante ; métastases hépatiques</td></tr>\n          <tr><td><strong>Conjuguée — <span class=\"kw-clinique\">cholestase</span>, obstacle sur <span class=\"kw-clinique\">les</span> petits canaux</strong></td><td><span class=\"kw-etio\">Cholangite biliaire primitive</span> (AC anti-mitochondries M2) ; <span class=\"kw-etio\">cholangite immuno-allergique</span> (surtout médicamenteuse) ; <span class=\"kw-etio\">cholangite sclérosante primitive</span> ; <span class=\"kw-etio\">mucoviscidose</span> ; mutation du transporteur canaliculaire MDR3</td></tr>\n          <tr><td><strong>Conjuguée — <span class=\"kw-clinique\">cholestase</span> sans obstacle</strong></td><td>Génétiques : <span class=\"kw-etio\">cholestase intra-hépatique familiale progressive</span> (PFIC), <span class=\"kw-clinique\">cholestase</span> récurrente bénigne, cholestase gravidique ;<br>Acquises (inhibition par cytokines pro-inflammatoires) : <span class=\"kw-etio\">hépatites aiguës</span>, <span class=\"kw-etio\">infections bactériennes sévères</span>, <span class=\"kw-etio\">angiocholite</span></td></tr>\n          <tr><td><strong>Conjuguée — atteinte du transport sans <span class=\"kw-clinique\">cholestase</span></strong></td><td><span class=\"kw-etio\">Syndrome de Rotor</span> ; <span class=\"kw-etio\">maladie de Dubin-Johnson</span></td></tr>\n          <tr><td><strong>Mixte</strong></td><td><span class=\"kw-alerte\">Insuffisance hépatocellulaire grave</span> (<span class=\"kw-def\">cirrhose</span>, <span class=\"kw-etio\">hépatite</span> aiguë) ; ictères de mécanismes multiples chez le malade en état grave</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire · 279 — <span class=\"kw-def\">Cirrhose</span> · 167 — Hépatites virales · 308 — Tumeur pancréas · 304 — Tumeur du foie · 213 — Anémie</em></p>","frequence":1},{"id":"278-8","rang":"B","rubrique":"Étiologies","titre":"Connaître les causes de l’obstruction de la voie biliaire principale","contenu":"<p>L'obstruction de la <strong>voie biliaire principale</strong> (VBP) est le mécanisme le plus fréquent d'<span class=\"kw-clinique\">ictère</span> cholestatique. <strong>Trois causes principales</strong> dominent.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Présentation clinique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Cancer de la tête du pancréas</span></strong></td><td><span class=\"kw-alerte\">Altération de l'état général</span> profonde ; <span class=\"kw-clinique\">ictère</span> souvent isolé « nu », <span class=\"kw-clinique\">prurigineux</span> ; <span class=\"kw-clinique\">grosse vésicule palpable indolore</span> en hypochondre droit ; douleur ép<span class=\"kw-chiffre\">iga</span>strique en barre ; <strong>habituellement pas de <span class=\"kw-clinique\">fièvre</span></strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Cholangiocarcinome</span></strong></td><td><span class=\"kw-clinique\">Ictère</span> <strong>sans <span class=\"kw-clinique\">fièvre</span> ni douleur</strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Lithiase de la VBP</span></strong></td><td><span class=\"kw-clinique\">Ictère</span> souvent <span class=\"kw-clinique\">précédé d'une douleur</span> biliaire ; <span class=\"kw-clinique\">fièvre</span> en cas d'<span class=\"kw-clinique\">angiocholite</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes moins fréquentes</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Adénopathie</span> (<span class=\"kw-etio\">tumorale</span> ou inflammatoire) comprimant la VBP.</li>\n        <li><span class=\"kw-etio\">Sténose post-opératoire</span> des voies biliaires.</li>\n        <li><span class=\"kw-etio\">Pancréatite chronique calcifiante</span> — compression de la VBP intrapancréatique.</li>\n        <li><span class=\"kw-etio\">Métastases hépatiques</span> — <span class=\"kw-clinique\">ictère</span> tardif, par compression ou <span class=\"kw-bio\">envahissement</span> de la VBP.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire · 308 — Tumeur pancréas · 281 — <span class=\"kw-def\">Pancréatite chronique</span></em></p>","frequence":1},{"id":"278-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les tableaux cliniques d’ictère selon l’étiologie","contenu":"<p>L'analyse clinique oriente d'emblée vers le mécanisme et l'étiologie de l'<span class=\"kw-clinique\">ictère</span>.</p>\n      <p><strong>Mécanisme — couleur des urines et des selles</strong> :</p>\n      <table >\n        <thead><tr><th>Prédominance</th><th>Urines</th><th>Selles</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">Bilirubine</span> non-conjuguée</strong></td><td><span class=\"kw-clinique\">Claires</span> (ou « coca-cola » si <span class=\"kw-etio\">hémolyse intravasculaire</span>)</td><td><span class=\"kw-clinique\">Normales</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Bilirubine conjuguée</span></strong></td><td><span class=\"kw-clinique\">Foncées, brunes</span></td><td><span class=\"kw-clinique\">Décolorées</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Orientation étiologique</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Prurit</span></strong> — toujours en faveur d'un <span class=\"kw-clinique\">ictère</span> <span class=\"kw-def\">cholestatique</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Grosse vésicule palpable</span></strong> — obstruction cholédocienne <span class=\"kw-etio\">néoplasique</span> (cancer du pancréas).</li>\n        <li><strong><span class=\"kw-clinique\">Douleur biliaire typique</span></strong> — <span class=\"kw-clinique\">ictère</span> probablement <span class=\"kw-etio\">lithiasique</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> autres colorations jaunes des téguments sont exceptionnelles : alimentation riche en <span class=\"kw-clinique\">légumes rouges ou orangés</span>, ou <span class=\"kw-clinique\">fluorescéine</span> utilisée pour l'<span class=\"kw-imagerie\">angiographie</span> rétinienne. Elles ne s'accompagnent pas d'une élévation de la bilirubinémie ni d'un <span class=\"kw-clinique\">ictère</span> conjonctival.</div>","frequence":0},{"id":"278-10","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques d’insuffisance hépatocellulaire grave","contenu":"<p>La gravité d'une <strong><span class=\"kw-alerte\">insuffisance hépatocellulaire</span></strong> (<span class=\"kw-bio\">IHC</span>) est définie par une <strong>triade</strong> de signes.</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Ictère</span></strong> — hyperbilirubinémie <span class=\"kw-bio\">mixte ou à prédominance conjuguée</span>, son intensité reflétant la sévérité de l'atteinte.</li>\n        <li><strong><span class=\"kw-clinique\">Encéphalopathie hépatique</span></strong>.</li>\n        <li><strong>Effondrement de l'hémostase</strong> — chute du <span class=\"kw-bio\">taux de prothrombine (TP)</span> et du <span class=\"kw-bio\">facteur V</span> <span class=\"kw-chiffre\">&lt; 50 %</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> L'association <span class=\"kw-clinique\">ictère</span> + encéphalopathie + <span class=\"kw-bio\">facteur V &lt; 50 %</span> signe une <span class=\"kw-bio\">IHC</span> <span class=\"kw-alerte\">grave</span>. La bilirubinémie est un paramètre intégré aux scores pronostiques <span class=\"kw-def\">Child-Pugh</span> et <span class=\"kw-def\">MELD</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span> · 167 — Hépatites virales · 337 — Intoxication aiguë</em></p>","frequence":0},{"id":"278-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications de l’insuffisance hépato-cellulaire grave","contenu":"<p><span class=\"kw-clinique\">Les</span> complications de l'<span class=\"kw-bio\">IHC</span> grave engagent le <span class=\"kw-alerte\">pronostic vital</span>.</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Encéphalopathie hépatique</span></strong> — sa survenue définit la gravité.</li>\n        <li><strong><span class=\"kw-alerte\">Hépatite fulminante</span></strong> — encéphalopathie apparaissant <span class=\"kw-chiffre\">&lt; 15 jours</span> après l'apparition de l'<span class=\"kw-clinique\">ictère</span>.</li>\n        <li><strong><span class=\"kw-alerte\">Hépatite subfulminante</span></strong> — encéphalopathie apparaissant entre <span class=\"kw-chiffre\">15 jours et 3 mois</span> après l'<span class=\"kw-clinique\">ictère</span>.</li>\n      </ul>\n      <p>On distingue par ailleurs l'<strong><span class=\"kw-alerte\">insuffisance hépatique aiguë (IHA) sévère</span></strong> : <span class=\"kw-bio\">TP &lt; 50 %</span> ou <span class=\"kw-bio\">facteur V &lt; 50 %</span>, <strong>en l'absence d'encéphalopathie</strong>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> En présence d'une encéphalopathie, la <span class=\"kw-def\">mortalité</span> spontanée atteint environ <span class=\"kw-chiffre\">80 %</span> : transfert immédiat vers un <span class=\"kw-ttt\">centre de transplantation hépatique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span> · 167 — Hépatites virales · 337 — Intoxication aiguë</em></p>","frequence":0},{"id":"278-12","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en première intention devant un ictère de l’adulte","contenu":"<p>Le bilan de <span class=\"kw-chiffre\">première intention</span> est <strong>systématique</strong> devant tout <span class=\"kw-clinique\">ictère</span> de l'adulte.</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">NFS</span></strong>.</li>\n        <li><strong>Bilan hépatique</strong> — <span class=\"kw-bio\">bilirubine totale</span> et <span class=\"kw-bio\">bilirubine conjuguée</span>, <span class=\"kw-bio\">ASAT</span>, <span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">GGT</span>, <span class=\"kw-bio\">PAL</span>.</li>\n      </ul>\n      <p>Ce bilan permet de classer l'<span class=\"kw-clinique\">ictère</span> et d'orienter la suite :</p>\n      <ul>\n        <li><strong>Si <span class=\"kw-bio\">bilirubine</span> libre avec anémie ou contexte d'hémolyse</strong> — <span class=\"kw-bio\">frottis sanguin</span>, <span class=\"kw-bio\">réticulocytes</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">haptoglobinémie</span>.</li>\n        <li><strong>Si <span class=\"kw-bio\">bilan hépatique</span> normal, sans anémie ni hémolyse</strong> — <span class=\"kw-etio\">syndrome de Gilbert</span> retenu : pas de <span class=\"kw-def\">suivi</span> nécessaire.</li>\n      </ul>","frequence":1},{"id":"278-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en deuxième intention (à visée étiologique) devant un ictère de l’adulte","contenu":"<p><span class=\"kw-clinique\">Les</span> examens de <span class=\"kw-chiffre\">deuxième intention</span> sont guidés par le type de <span class=\"kw-bio\">bilirubine</span> et les données de l'<span class=\"kw-imagerie\">échographie</span>.</p>\n      <ul>\n        <li><strong>Si <span class=\"kw-bio\">bilirubine</span> mixte</strong> — <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">facteur V</span>, <span class=\"kw-bio\">albuminémie</span>, bilan à la recherche d'une <span class=\"kw-def\">cirrhose</span> ou d'une <span class=\"kw-etio\">hépatite</span> aiguë.</li>\n        <li><strong>Si <span class=\"kw-clinique\">cholestase</span>, voies biliaires non dilatées</strong> — <span class=\"kw-bio\">AC anti-mitochondries M2</span> (cholangite biliaire primitive), <span class=\"kw-imagerie\">cholangio-IRM</span> (<span class=\"kw-etio\">cholangite sclérosante primitive</span>), <span class=\"kw-bio\">sérologies</span> virales, ± <span class=\"kw-bio\">ponction-biopsie hépatique</span>.</li>\n        <li><strong>Si <span class=\"kw-clinique\">cholestase</span>, voies biliaires dilatées</strong> — objectif : <strong>identifier le siège de l'obstacle</strong>.</li>\n      </ul>\n      <p><strong>Imagerie des voies biliaires</strong> — l'examen suivant, plus coûteux ou plus invasif, n'est réalisé que lorsque le précédent n'a pas apporté le diagnostic :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie abdominale</span></strong></td><td>À réaliser en premier lieu ; recherche une dilatation des voies biliaires</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">TDM injectée</span></strong></td><td>Plus sensible que l'<span class=\"kw-imagerie\">échographie</span> pour <span class=\"kw-clinique\">les</span> affections pancréatiques ; expose à l'<span class=\"kw-clinique\">irradiation</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">IRM et cholangio-IRM</span></strong></td><td>Non irradiante, non invasive ; a remplacé la <span class=\"kw-imagerie\">CPRE</span> à visée diagnostique</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Écho-endoscopie</span></strong></td><td>Examen le plus performant pour la <span class=\"kw-clinique\">lithiase de la VBP</span> et l'analyse du pancréas ; permet des <span class=\"kw-bio\">biopsies</span> dirigées</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">CPRE</span></strong></td><td>Désormais à visée <span class=\"kw-ttt\">thérapeutique</span> (sphinctérotomie, extraction de calcul, prothèse) ; complications : <span class=\"kw-alerte\">pancréatite aiguë</span> (<span class=\"kw-chiffre\">5 %</span>), hémorragie, perforation duodénale</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Cholangiographie percutanée</span></strong></td><td>Très invasive ; utile en cas d'échec de la <span class=\"kw-imagerie\">CPRE</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 358 — <span class=\"kw-def\">Pancréatite aiguë</span></em></p>","frequence":0},{"id":"278-14","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les situations d’urgence devant un ictère de l’adulte","contenu":"<p>Deux situations d'<span class=\"kw-alerte\">urgence</span> doivent être identifiées devant un <span class=\"kw-clinique\">ictère</span> de l'adulte.</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Angiocholite</span></strong> — à évoquer devant <strong>tout <span class=\"kw-clinique\">ictère</span> fébrile</strong> ; impose la réalisation d'<span class=\"kw-bio\">hémocultures</span>.</li>\n        <li><strong><span class=\"kw-alerte\">Insuffisance hépatique</span></strong> — sur foie cirrhotique, sur foie sain, ou au <span class=\"kw-def\">stade</span> terminal d'un cancer du foie.</li>\n      </ul>\n      <p><strong>Conduite à tenir</strong> devant tout <span class=\"kw-clinique\">ictère</span> :</p>\n      <ul>\n        <li>Doser <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">transaminases</span> et le <span class=\"kw-bio\">TP</span>.</li>\n        <li>Si le <span class=\"kw-bio\">TP</span> est abaissé — doser le <span class=\"kw-bio\">facteur V</span>.</li>\n        <li><span class=\"kw-bio\">Facteur V &lt; 50 %</span> — adresser le malade à un <span class=\"kw-ttt\">centre de transplantation hépatique</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute atteinte hépatique aiguë impose de rechercher une prise de <span class=\"kw-ttt\">paracétamol</span>, même à dose thérapeutique. En cas de prise : administration en urgence de <span class=\"kw-ttt\">N-acétylcystéine</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire · 279 — <span class=\"kw-def\">Cirrhose</span> · 337 — Intoxication aiguë</em></p>","frequence":0},{"id":"278-15","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’objectif de l’imagerie par échographie dans l’exploration d’un ictère à bilirubine conjuguée","contenu":"<p>L'<span class=\"kw-imagerie\">échographie abdominale</span> est l'examen de <strong><span class=\"kw-chiffre\">première intention</span></strong> dans l'exploration d'un <span class=\"kw-clinique\">ictère</span> à <span class=\"kw-bio\">bilirubine conjuguée</span>.</p>\n      <p><strong>Objectif principal</strong> — rechercher une <strong><span class=\"kw-radio\">dilatation des voies biliaires</span></strong>, signe d'un obstacle : des voies biliaires intra-hépatiques <span class=\"kw-radio\">diffusément et harmonieusement dilatées</span> traduisent un obstacle sur la VBP ou sur la convergence des canaux hépatiques.</p>\n      <p><strong>Déterminer le siège de l'obstacle</strong> :</p>\n      <table >\n        <thead><tr><th>Siège</th><th>Aspect échographique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Canal hépatique commun</strong></td><td><span class=\"kw-radio\">Cholédoque non dilaté</span>, <span class=\"kw-clinique\">vésicule</span> normale</td></tr>\n          <tr><td><strong>Canal cholédoque</strong></td><td><span class=\"kw-radio\">Vésicule et canal hépatique commun dilatés</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres apports</strong> :</p>\n      <ul>\n        <li>Affirme une <span class=\"kw-etio\">lithiase biliaire</span> — formation <span class=\"kw-radio\">hyperéchogène avec cône d'ombre postérieur</span> — sans pouvoir l'écarter.</li>\n        <li>Une <span class=\"kw-radio\">dilatation de la vésicule biliaire</span> indique un obstacle cholédocien sur <span class=\"kw-clinique\">vésicule</span> saine, en faveur d'une cause <span class=\"kw-etio\">néoplasique</span> (cancer du pancréas, cholangiocarcinome).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> La dilatation des voies biliaires peut <span class=\"kw-alerte\">manquer</span> malgré un obstacle réel : <span class=\"kw-imagerie\">obstruction récente</span> (migration lithiasique), voies biliaires <span class=\"kw-imagerie\">scléreuses</span>, ou <span class=\"kw-imagerie\">parenchyme hépatique rigide</span> (<span class=\"kw-def\">cirrhose</span>). Une <span class=\"kw-imagerie\">échographie</span> normale n'élimine pas un obstacle.</div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré</strong></p><ul><li><span class=\"kw-alerte\">urgence vitale</span> si <span class=\"kw-clinique\">ictère fébrile</span> ou <span class=\"kw-clinique\">encéphalopathie hépatique</span></li></ul><p><strong><span class=\"kw-clinique\">Angiocholite</span></strong></p><ul><li>à évoquer devant tout <span class=\"kw-clinique\">ictère fébrile</span> → <span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-ttt\">antibiothérapie</span> sans délai</li></ul><p><strong><span class=\"kw-bio\">IHC</span> grave</strong></p><ul><li><span class=\"kw-bio\">facteur V</span> <span class=\"kw-chiffre\">&lt; 50 %</span> → transfert immédiat en <span class=\"kw-ttt\">centre de transplantation hépatique</span></li></ul><p><strong>Fulminante</strong></p><ul><li><span class=\"kw-clinique\">encéphalopathie</span> <span class=\"kw-chiffre\">&lt; 15 jours</span> après l'<span class=\"kw-clinique\">ictère</span></li><li>subfulminante entre <span class=\"kw-chiffre\">15 j et 3 mois</span></li></ul><p><strong><span class=\"kw-ttt\">Paracétamol</span></strong></p><ul><li>toute atteinte hépatique aiguë → <span class=\"kw-ttt\">N-acétylcystéine</span> en <span class=\"kw-alerte\">urgence</span>, <em>même à dose thérapeutique</em></li></ul><p><strong>Néonatal</strong></p><ul><li><span class=\"kw-etio\">atrésie des voies biliaires</span> et <span class=\"kw-etio\">allo-immunisation érythrocytaire materno-fœtale</span> = urgences</li><li>risque d'<span class=\"kw-alerte\">ictère nucléaire</span> irréversible</li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">syndrome de Gilbert</span> isolé — pas de <span class=\"kw-def\">suivi</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> tout <span class=\"kw-clinique\">ictère cholestatique</span> nouveau, <span class=\"kw-clinique\">ictère hémolytique</span>, <span class=\"kw-alerte\">IHC</span> modérée pour bilan étiologique et <span class=\"kw-def\">surveillance</span>.<br><strong>Centre spécialisé (transplantation) :</strong> <span class=\"kw-bio\">facteur V</span> <span class=\"kw-chiffre\">&lt; 50 %</span>, <span class=\"kw-clinique\">encéphalopathie hépatique</span>, <span class=\"kw-alerte\">hépatite fulminante</span> ou subfulminante.<br><strong>Néonatal :</strong> maternité avec <span class=\"kw-def\">dépistage</span> <span class=\"kw-bio\">BTc</span> <span class=\"kw-chiffre\">≥ 1</span>×/j ; <span class=\"kw-ttt\">réa néonatale</span> si signes de sévérité ou risque d'<span class=\"kw-alerte\">ictère nucléaire</span> ; <span class=\"kw-ttt\">chirurgie pédiatrique</span> en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-etio\">atrésie des voies biliaires</span> (la précocité conditionne le <span class=\"kw-def\">pronostic</span>).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Ictère fébrile</span> — évoquer <span class=\"kw-etio\">angiocholite</span> en premier</li><li><span class=\"kw-alerte\">Encéphalopathie hépatique</span> — signe une <span class=\"kw-bio\">IHC</span> grave</li><li><span class=\"kw-bio\">Facteur V</span> <span class=\"kw-chiffre\">&lt; 50 %</span> ou <span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 50 %</span></li><li><span class=\"kw-bio\">Transaminases</span> <span class=\"kw-chiffre\">&gt; 20 N</span> — <span class=\"kw-etio\">hépatite aiguë</span></li><li><span class=\"kw-clinique\">Grosse vésicule palpable indolore</span> — <span class=\"kw-etio\">cancer de la tête du pancréas</span></li><li><span class=\"kw-alerte\">Altération de l'état général</span> profonde avec <span class=\"kw-clinique\">ictère nu prurigineux</span></li><li>NN — <span class=\"kw-alerte\">atteinte des plantes des pieds</span> (intensité de l'<span class=\"kw-clinique\">ictère</span>)</li><li>NN — <span class=\"kw-clinique\">ictère</span> <span class=\"kw-chiffre\">&lt; 24 h de vie</span> (probable <span class=\"kw-etio\">hémolyse par allo-immunisation</span>)</li><li>NN — durée <span class=\"kw-chiffre\">&gt; 10 jours</span> à terme ou <span class=\"kw-chiffre\">&gt; J14</span> chez le prématuré</li><li>NN — perte pondérale <span class=\"kw-chiffre\">&gt; 8 %</span>, <span class=\"kw-clinique\">selles décolorées</span>, <span class=\"kw-clinique\">urines foncées</span></li></ul>","principes":"<p><strong>Démarche :</strong> typer la <span class=\"kw-bio\">bilirubine</span> (libre <span class=\"kw-bio\">vs</span> conjuguée <span class=\"kw-bio\">vs</span> mixte) → bilan ciblé → étiologie → traitement spécifique.<br><strong>Toujours :</strong> doser <span class=\"kw-bio\">TP</span> + <span class=\"kw-bio\">facteur V</span> pour quantifier la <span class=\"kw-alerte\">gravité</span>.</p><p><strong>1ʳᵉ intention systématique</strong></p><ul><li><span class=\"kw-bio\">NFS</span> + <span class=\"kw-bio\">bilan hépatique</span> (<span class=\"kw-bio\">bilirubine totale + conjuguée</span>, <span class=\"kw-bio\">ASAT</span>, <span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">GGT</span>, <span class=\"kw-bio\">PAL</span>)</li></ul><p><strong>Si <span class=\"kw-bio\">bilirubine</span> libre + suspicion d'hémolyse</strong></p><ul><li><span class=\"kw-bio\">frottis</span>, <span class=\"kw-bio\">réticulocytes</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">haptoglobinémie</span></li></ul><p><strong>Si <span class=\"kw-bio\">bilirubine conjuguée</span></strong></p><ul><li><span class=\"kw-imagerie\">échographie abdominale</span> systématique</li><li>selon : <span class=\"kw-bio\">AC anti-mitochondries M2</span>, <span class=\"kw-imagerie\">cholangio-IRM</span>, <span class=\"kw-bio\">sérologies</span> virales, ± <span class=\"kw-bio\">ponction-biopsie hépatique</span></li></ul><p><strong>Obstacle sur la VBP</strong></p><ul><li><span class=\"kw-ttt\">CPRE thérapeutique</span> (sphinctérotomie + extraction de calcul, prothèse si sténose)</li><li><span class=\"kw-imagerie\">écho-endoscopie</span> en cas de doute diagnostique</li></ul><p><strong><span class=\"kw-alerte\">IHC grave</span></strong></p><ul><li><span class=\"kw-ttt\">N-acétylcystéine</span> en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-ttt\">paracétamol</span></li><li>transfert immédiat en <span class=\"kw-ttt\">centre de transplantation hépatique</span></li></ul><p><strong><span class=\"kw-etio\">Angiocholite</span></strong></p><ul><li><span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-ttt\">antibiothérapie</span> probabiliste + <span class=\"kw-ttt\">drainage</span> biliaire (<span class=\"kw-ttt\">CPRE</span>)</li></ul><p><strong>NN <span class=\"kw-bio\">bilirubine</span> libre</strong></p><ul><li><span class=\"kw-ttt\">photothérapie</span> par lumière bleue</li><li>± <span class=\"kw-ttt\">exsanguino-transfusion</span> si très sévère</li><li>± <span class=\"kw-ttt\">Ig polyvalentes IV</span> si <span class=\"kw-etio\">allo-immunisation</span> ABO/Rhésus</li></ul><p><strong>NN <span class=\"kw-bio\">bilirubine conjuguée</span></strong></p><ul><li><span class=\"kw-ttt\">vitamine K parentérale</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-alerte\">risque hémorragique</span>) + avis <span class=\"kw-ttt\">chirurgie pédiatrique</span> si <span class=\"kw-etio\">atrésie des voies biliaires</span></li></ul><p><strong>NN ictères bénins</strong></p><ul><li>abstention thérapeutique (<span class=\"kw-etio\">ictère simple</span>, <span class=\"kw-etio\">ictère au lait de mère</span>) — <span class=\"kw-ci\">ne jamais interrompre l'allaitement maternel</span></li></ul>","suivi":"<p><strong>Gilbert :</strong> pas de <span class=\"kw-def\">suivi</span> nécessaire — diagnostic d'élimination.<br><strong><span class=\"kw-bio\">IHC</span> :</strong> <span class=\"kw-bio\">TP</span> et <span class=\"kw-bio\">facteur V</span> répétés, <span class=\"kw-bio\">transaminases</span>, clinique de l'<span class=\"kw-clinique\">encéphalopathie</span> — basculer en grave si dégradation.<br><strong>Post-<span class=\"kw-ttt\">CPRE</span> :</strong> surveiller <span class=\"kw-alerte\">pancréatite aiguë</span> (<span class=\"kw-chiffre\">5 %</span>), hémorragie (<span class=\"kw-chiffre\">1 %</span>), perforation duodénale (<span class=\"kw-chiffre\">0,1–0,6 %</span>).<br><strong><span class=\"kw-clinique\">Cholestase</span> prolongée :</strong> dépister carences en <span class=\"kw-bio\">vitamines A, D, E, K</span> (<span class=\"kw-clinique\">ostéopénie</span>, <span class=\"kw-bio\">TP bas avec facteur V normal</span>).<br><strong>Néonatal :</strong> <span class=\"kw-bio\">BTc</span> <span class=\"kw-chiffre\">≥ 1</span>×/j en maternité, sortie autorisée si <span class=\"kw-chiffre\">&lt; 75ᵉ percentile</span> ; bilan élargi si persistance <span class=\"kw-chiffre\">&gt; J7</span> (à terme) ou <span class=\"kw-chiffre\">&gt; J14</span> (prématuré).</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Ictère de l'adulte — Bilirubine totale + conjuguée + NFS + bilan hépatique","detail":"<h4>Démarche diagnostique — <span class=\"kw-clinique\">ictère</span> de l'adulte — Premier tri sur la <span class=\"kw-bio\">bilirubine</span> prédominante</h4>","branches":[{"to":"q-libre","label":"Non-conjuguée > 70%","color":"amber"},{"to":"q-conj","label":"Conjuguée","color":"amber"},{"to":"q-ihc","label":"Mixte","color":"red"}]},{"id":"q-libre","kind":"decision","label":"Anémie + signes d'hémolyse ? — Frottis · Rétic · Hapto · LDH","branches":[{"to":"t-hemolyse","label":"Oui","color":"amber"},{"to":"t-gilbert","label":"Non + BH normal","color":"green"}]},{"id":"t-hemolyse","kind":"terminal","label":"Ictère hémolytique","color":"amber","detail":"<h4>Biologie</h4><ul><li><span class=\"kw-bio\">Réticulocytes</span> augmentés (avec ou sans anémie)</li><li><span class=\"kw-bio\">Haptoglobine</span> effondrée</li><li><span class=\"kw-bio\">LDH</span> augmentées</li><li><span class=\"kw-bio\">Frottis sanguin</span> — analyser l'aspect des GR</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Hémolyses constitutionnelles</span> (sphérocytose, déficit en G6PD, pyruvate kinase)</li><li><span class=\"kw-etio\">Hémolyses acquises</span> (auto-immunes, mécaniques, médicamenteuses)</li></ul><h4>Renvoi</h4><ul><li>Item <strong>213</strong> — Anémie</li></ul>"},{"id":"t-gilbert","kind":"terminal","label":"Syndrome de Gilbert","color":"green","detail":"<h4><span class=\"kw-def\">Critères diagnostiques</span></h4><ul><li><span class=\"kw-bio\">Bilirubine libre</span> <span class=\"kw-chiffre\">&lt; 80 µmol/L</span></li><li>Tests hépatiques rigoureusement normaux</li><li>Pas d'anémie ni de réticulocytose</li></ul><h4>Fluctuations</h4><ul><li>Bilirubinémie augmentée par <span class=\"kw-clinique\">jeûne</span>, <span class=\"kw-clinique\">fatigue</span>, infections intercurrentes ; diminuée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">inducteurs enzymatiques</span></li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Aucun — le <span class=\"kw-clinique\">syndrome de Gilbert</span> n'est pas une maladie</li></ul><h4>Piège</h4><ul><li>Majore la <span class=\"kw-alerte\">toxicité de l'<span class=\"kw-ttt\">irinotécan</span></span> (élimination par glucuroconjugaison)</li></ul>"},{"id":"q-conj","kind":"decision","label":"Prurit + ↑ PAL/γGT ? — Critères de cholestase","branches":[{"to":"q-echo","label":"Oui — cholestase","color":"amber"},{"to":"t-transport","label":"Non — sans cholestase","color":"green"}]},{"id":"q-echo","kind":"decision","label":"Échographie : voies biliaires dilatées ? — Examen de 1ʳᵉ intention","branches":[{"to":"t-obstacle-gros","label":"Oui","color":"amber"},{"to":"t-obstacle-petits","label":"Non","color":"amber"}]},{"id":"t-obstacle-gros","kind":"terminal","label":"Obstacle sur gros canaux","color":"amber","detail":"<h4>Identifier le siège</h4><ul><li><span class=\"kw-imagerie\">TDM injectée</span> — sensible pour <span class=\"kw-clinique\">les</span> affections pancréatiques</li><li><span class=\"kw-imagerie\">Bili-IRM / IRM hépatique</span> — non irradiant, a remplacé la <span class=\"kw-imagerie\">CPRE</span> diagnostique</li><li><span class=\"kw-imagerie\">Écho-endoscopie</span> — référence pour lithiase VBP, permet des <span class=\"kw-bio\">biopsies</span> dirigées</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Lithiase de la VBP</span> ± <span class=\"kw-alerte\">angiocholite</span> (<span class=\"kw-clinique\">ictère</span> fébrile)</li><li><span class=\"kw-etio\">Cancer de la tête du pancréas</span> — <span class=\"kw-clinique\">AEG</span>, grosse <span class=\"kw-clinique\">vésicule</span> palpable indolore, pas de fièvre</li><li><span class=\"kw-etio\">Cholangiocarcinome</span> — <span class=\"kw-clinique\">ictère</span> sans <span class=\"kw-clinique\">fièvre</span> ni douleur</li><li><span class=\"kw-etio\">Adénopathie comprimant la VBP</span>, sténose post-opératoire, métastases hépatiques</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">CPRE thérapeutique</span> (sphinctérotomie + extraction de calcul, prothèse si sténose). Surveiller <span class=\"kw-alerte\">pancréatite aiguë</span> (<span class=\"kw-chiffre\">5 %</span>)</li></ul><h4>Renvois</h4><ul><li>Items <strong>277</strong> — Lithiase biliaire · <strong>308</strong> — Tumeur du pancréas · <strong>281</strong> — <span class=\"kw-clinique\">Pancréatite chronique</span></li></ul>"},{"id":"t-obstacle-petits","kind":"terminal","label":"Atteinte petits canaux ou hépatocellulaire","color":"amber","detail":"<h4>Bilan ciblé</h4><ul><li><span class=\"kw-bio\">AC anti-mitochondries M2</span> → <span class=\"kw-etio\">cholangite biliaire primitive</span></li><li><span class=\"kw-imagerie\">Cholangio-IRM</span> → <span class=\"kw-etio\">cholangite sclérosante primitive</span> (irrégularités VB intra et extra-hépatiques)</li><li><span class=\"kw-bio\">Sérologies</span> virales — recherche d'une <span class=\"kw-etio\">hépatite aiguë</span></li><li>± <span class=\"kw-bio\">Ponction-biopsie hépatique</span> si AC et cholangio-<span class=\"kw-imagerie\">IRM</span> négatifs</li></ul><h4>Autres étiologies</h4><ul><li><span class=\"kw-etio\">Cholangite immuno-allergique</span> (<span class=\"kw-ttt\">amoxicilline</span>-clavulanate, <span class=\"kw-ttt\">sulfamides</span>, macrolides) — <span class=\"kw-clinique\">fièvre</span> + hyperéosinophilie</li><li><span class=\"kw-etio\">Mucoviscidose</span>, mutation du transporteur MDR3</li><li><span class=\"kw-etio\">Hépatites aiguës</span> (<span class=\"kw-etio\">virale</span>, alcoolique, <span class=\"kw-etio\">auto-immune</span>, médicamenteuse)</li><li><span class=\"kw-etio\">Infections bactériennes sévères</span> (PNA, <span class=\"kw-clinique\">PAC</span>, leptospirose, typhoïde)</li></ul><h4>Renvois</h4><ul><li>Items <strong>167</strong> — Hépatites virales · <strong>279</strong> — Cirrhose</li></ul>"},{"id":"t-transport","kind":"terminal","label":"Atteinte du transport sans cholestase","color":"green","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Syndrome de Rotor</span></li><li><span class=\"kw-etio\">Maladie de Dubin-Johnson</span></li></ul><h4>Caractéristiques</h4><ul><li>Affections génétiques rarissimes et bénignes — atteinte isolée du transport canaliculaire de la <span class=\"kw-bio\">bilirubine conjuguée</span> (pas des acides biliaires, sinon <span class=\"kw-clinique\">cholestase</span> associée)</li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Aucun traitement, pas de complication évolutive</li></ul>"},{"id":"q-ihc","kind":"decision","label":"<span class=\"kw-bio\">Facteur V</span> < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> %</span> ? — <span class=\"kw-bio\">TP</span> + Facteur V indispensables","branches":[{"to":"t-ihc-grave","label":"Oui","color":"red"},{"to":"t-ihc-mod","label":"Non","color":"amber"}]},{"id":"t-ihc-grave","kind":"terminal","label":"IHC grave — urgence vitale","color":"red","detail":"<h4><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span></h4><ul><li><span class=\"kw-clinique\">Encéphalopathie hépatique</span></li><li><span class=\"kw-bio\">Facteur V</span> <span class=\"kw-chiffre\">&lt; 50 %</span></li><li><span class=\"kw-def\">Mortalité</span> spontanée environ <span class=\"kw-chiffre\">80 %</span></li></ul><h4>Fulminante <span class=\"kw-bio\">vs</span> subfulminante</h4><ul><li><span class=\"kw-alerte\">Hépatite fulminante</span> — encéphalopathie <span class=\"kw-chiffre\">&lt; 15 jours</span> après l'<span class=\"kw-clinique\">ictère</span></li><li><span class=\"kw-alerte\">Hépatite subfulminante</span> — encéphalopathie entre <span class=\"kw-chiffre\">15 jours et 3 mois</span></li></ul><h4>Conduite immédiate</h4><ul><li>Transfert en <span class=\"kw-ttt\">centre de transplantation hépatique</span></li><li>Rechercher <span class=\"kw-ttt\">paracétamol</span> systématiquement → <span class=\"kw-ttt\">N-acétylcystéine</span> en <span class=\"kw-alerte\">urgence</span></li><li>Bilan étiologique en parallèle (<span class=\"kw-bio\">sérologies</span> virales, AI, <span class=\"kw-etio\">alcool</span>, médicaments)</li></ul><h4>Renvois</h4><ul><li>Items <strong>279</strong> — Cirrhose · <strong>167</strong> — Hépatites virales · <strong>337</strong> — Intoxication aiguë</li></ul>"},{"id":"t-ihc-mod","kind":"terminal","label":"IHC modérée / hépatite aiguë","color":"amber","detail":"<h4>Définition</h4><ul><li><span class=\"kw-alerte\">IHA sévère</span> = <span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 50 %</span> ou <span class=\"kw-bio\">facteur V</span> <span class=\"kw-chiffre\">&lt; 50 %</span>, <em>en l'absence d'encéphalopathie</em></li></ul><h4>Bilan étiologique</h4><ul><li><span class=\"kw-bio\">Transaminases</span> — si <span class=\"kw-chiffre\">&gt; 20 N</span>, évoquer une <span class=\"kw-etio\">hépatite aiguë</span></li><li><span class=\"kw-bio\">Sérologies</span> virales (<span class=\"kw-etio\">VHA</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>, <span class=\"kw-etio\">VHE</span>, <span class=\"kw-etio\">HSV</span>)</li><li>Bilan <span class=\"kw-etio\">auto-immun</span>, <span class=\"kw-etio\">alcool</span>, médicaments — en particulier <span class=\"kw-ttt\">paracétamol</span></li><li>Recherche d'une <span class=\"kw-def\">cirrhose</span> sous-jacente (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">élastométrie</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">facteur V</span>, transaminases, clinique de l'encéphalopathie — basculer en <span class=\"kw-bio\">IHC</span> grave si dégradation</li></ul><h4>Renvois</h4><ul><li>Items <strong>279</strong> · <strong>167</strong> · <strong>304</strong> — Tumeur du foie</li></ul>"}]},"cards":[{"i":"27a64dd380eb","n":278,"o":"278-1","u":"Définition","t":"Connaître la définition d’un ictère du nouveau-né","q":"Quel signe clinique chez le nouveau-né fait suspecter un ictère intense ?","a":"<p>L'atteinte des <strong>plantes des pieds</strong> est un repère clinique témoignant de l'intensité de l'ictère et doit être systématiquement vérifiée.</p>"},{"i":"4587eccd6157","n":278,"o":"278-1","u":"Définition","t":"Connaître la définition d’un ictère du nouveau-né","q":"Quels mécanismes physiopathologiques expliquent l'ictère du nouveau-né ?","a":"<ul><li>Une <strong>hémolyse physiologique</strong> survenant à la naissance.</li><li>Une <strong>immaturité hépatique</strong>, avec un retard de maturation de la bilirubine glucuronyl-transférase.</li><li>Une <strong>augmentation du cycle entéro-hépatique</strong>, due à l'absence de flore bactérienne intestinale qui favorise la réabsorption de la bilirubine.</li></ul>"},{"i":"a576f4ae2786","n":278,"o":"278-1","u":"Définition","t":"Connaître la définition d’un ictère du nouveau-né","q":"Quelle est la définition clinique d'un ictère du nouveau-né ?","a":"<p>L'ictère du nouveau-né est une <strong>coloration jaune</strong> de la peau et des conjonctives, s'étendant dans le sens <strong>céphalo-caudal</strong> (du visage vers les extrémités).</p>"},{"i":"01c576c08f11","n":278,"o":"278-10","u":"Identifier une urgence","t":"Connaître les signes cliniques d’insuffisance hépatocellulaire grave","q":"Quel est le paramètre du bilan de coagulation permettant d'évaluer la gravité de l'insuffisance hépatocellulaire ?","a":"<p>Le paramètre essentiel évaluant la gravité de l'insuffisance hépatocellulaire est le <strong>taux de prothrombine (TP)</strong> et le <strong>facteur V</strong>. Un effondrement de ces deux facteurs <strong>< 50 %</strong> est un signe de gravité.</p>"},{"i":"9521b53dc526","n":278,"o":"278-10","u":"Identifier une urgence","t":"Connaître les signes cliniques d’insuffisance hépatocellulaire grave","q":"Comment est définie l'insuffisance hépatocellulaire (IHC) grave ?","a":"<p>L'insuffisance hépatocellulaire grave est définie par la <strong>triade</strong> associant :</p><ul><li>Un <strong>ictère</strong>.</li><li>Une <strong>encéphalopathie hépatique</strong>.</li><li>Un <strong>effondrement de l'hémostase</strong> avec un taux de prothrombine (TP) et du facteur V <strong>inférieur à 50 %</strong>.</li></ul>"},{"i":"bb9d642dcb8d","n":278,"o":"278-10","u":"Identifier une urgence","t":"Connaître les signes cliniques d’insuffisance hépatocellulaire grave","q":"Quel est le type d'hyperbilirubinémie retrouvé dans l'insuffisance hépatocellulaire grave ?","a":"<p>Dans l'insuffisance hépatocellulaire grave, l'hyperbilirubinémie est de type <strong>mixte ou à prédominance conjuguée</strong>. Son intensité reflète la sévérité de l'atteinte hépatique.</p>"},{"i":"e53a070e3ea4","n":278,"o":"278-10","u":"Identifier une urgence","t":"Connaître les signes cliniques d’insuffisance hépatocellulaire grave","q":"Dans quels scores pronostiques la bilirubinémie est-elle un paramètre intégré ?","a":"<p>La bilirubinémie est un paramètre intégré aux scores pronostiques tels que le <strong>Child-Pugh</strong> et le <strong>MELD</strong>.</p>"},{"i":"0da5cc0ef91c","n":278,"o":"278-11","u":"Diagnostic positif","t":"Connaître les complications de l’insuffisance hépato-cellulaire grave","q":"Quelle complication neuro-psychiatrique, survenant au cours de l'insuffisance hépato-cellulaire grave, en définit la gravité ?","a":"<p>La complication qui définit la gravité de l'insuffisance hépato-cellulaire grave est l'<strong>encéphalopathie hépatique</strong>.</p>"},{"i":"1916a6449eb8","n":278,"o":"278-11","u":"Diagnostic positif","t":"Connaître les complications de l’insuffisance hépato-cellulaire grave","q":"Dans le contexte de l'insuffisance hépato-cellulaire grave, quelle est la définition d'une hépatite subfulminante ?","a":"<p>Une hépatite subfulminante est caractérisée par l'apparition d'une <strong>encéphalopathie hépatique</strong> entre <strong>15 jours et 3 mois après l'apparition de l'ictère</strong>.</p>"},{"i":"289000f433b5","n":278,"o":"278-11","u":"Diagnostic positif","t":"Connaître les complications de l’insuffisance hépato-cellulaire grave","q":"Quel message clinique essentiel doit retenir le praticien face à une insuffisance hépato-cellulaire grave avec encéphalopathie ?","a":"<p>Face à une insuffisance hépato-cellulaire grave avec encéphalopathie, la <strong>mortalité spontanée peut atteindre environ 80%</strong>. Il s'agit d'une <strong>urgence vitale</strong> qui nécessite un <strong>transfert immédiat vers un centre de transplantation hépatique</strong>.</p>"},{"i":"92080000cdf1","n":278,"o":"278-11","u":"Diagnostic positif","t":"Connaître les complications de l’insuffisance hépato-cellulaire grave","q":"Comment définit-on une hépatite fulminante spécifiquement dans le cadre de l'insuffisance hépato-cellulaire grave ?","a":"<p>Une hépatite fulminante est définie par l'apparition d'une <strong>encéphalopathie hépatique</strong> dans les <strong>15 jours suivant l'apparition de l'ictère</strong>.</p>"},{"i":"c8a38aa0efe2","n":278,"o":"278-11","u":"Diagnostic positif","t":"Connaître les complications de l’insuffisance hépato-cellulaire grave","q":"Quels sont les critères diagnostiques d'une insuffisance hépatique aiguë sévère, en l'absence d'encéphalopathie hépatique ?","a":"<p>L'insuffisance hépatique aiguë sévère est définie par un <strong>TP inférieur à 50%</strong> ou un <strong>facteur V inférieur à 50%</strong>, en l'absence d'encéphalopathie hépatique.</p>"},{"i":"c5a7e7cee2c2","n":278,"o":"278-12","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en première intention devant un ictère de l’adulte","q":"Quels sont les examens biologiques de première intention systématiques à réaliser devant un ictère de l'adulte ?","a":"<p>Devant tout ictère de l'adulte, le bilan biologique de première intention inclut :</p><ul><li>Une <strong>Numération Formule Sanguine (NFS)</strong>.</li><li>Un <strong>bilan hépatique</strong> comprenant la <strong>bilirubine totale</strong>, la <strong>bilirubine conjuguée</strong>, les <strong>ASAT</strong>, les <strong>ALAT</strong>, les <strong>Gamma-GT (GGT)</strong> et les <strong>Phosphatases Alcalines (PAL)</strong>.</li></ul>"},{"i":"d9d24fc595e6","n":278,"o":"278-12","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en première intention devant un ictère de l’adulte","q":"Quel diagnostic doit être évoqué et quelle est la prise en charge si le bilan hépatique est normal et qu'il n'y a ni anémie ni signes d'hémolyse devant un ictère de l'adulte ?","a":"<p>Si le bilan hépatique est normal et qu'il n'y a ni anémie ni signes d'hémolyse devant un ictère de l'adulte, le diagnostic de <strong>syndrome de Gilbert</strong> doit être retenu. Dans cette situation, <strong>aucun suivi particulier n'est nécessaire</strong>.</p>"},{"i":"fab2357f0e0a","n":278,"o":"278-12","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en première intention devant un ictère de l’adulte","q":"Quels examens complémentaires sont à réaliser en plus du bilan initial si un ictère est à prédominance de bilirubine libre avec anémie ou contexte d'hémolyse ?","a":"<p>Si un ictère est à prédominance de bilirubine libre avec anémie ou contexte d'hémolyse, des examens complémentaires supplémentaires sont nécessaires pour explorer l'hémolyse :</p><ul><li>Un <strong>frottis sanguin</strong>.</li><li>Un dosage des <strong>réticulocytes</strong>.</li><li>Un dosage des <strong>LDH (Lactate Déshydrogénase)</strong>.</li><li>Un dosage de l'<strong>haptoglobinémie</strong>.</li></ul>"},{"i":"85b988d06e3f","n":278,"o":"278-14","u":"Identifier une urgence","t":"Connaître les situations d’urgence devant un ictère de l’adulte","q":"Quels sont les deux situations d'urgence principales à identifier devant un ictère de l'adulte ?","a":"<p>Les deux situations d'urgence principales sont :</p><ul><li>Une <strong>angiocholite</strong>.</li><li>Une <strong>insuffisance hépatique</strong>.</li></ul>"},{"i":"a71f8334f464","n":278,"o":"278-14","u":"Identifier une urgence","t":"Connaître les situations d’urgence devant un ictère de l’adulte","q":"Quel toxique et son antidote doivent être systématiquement recherchés et administrés en urgence devant une atteinte hépatique aiguë, même en l'absence d'ictère ?","a":"<p>Devant toute atteinte hépatique aiguë, il faut systématiquement rechercher une prise de <strong>paracétamol</strong>, même à dose thérapeutique. En cas de prise, l'administration en urgence de <strong>N-acétylcystéine</strong> est indiquée.</p>"},{"i":"bb5be833d035","n":278,"o":"278-14","u":"Identifier une urgence","t":"Connaître les situations d’urgence devant un ictère de l’adulte","q":"Quelle est la conduite à tenir systématique et les examens clés devant tout ictère chez l'adulte ?","a":"<p>Devant tout ictère, la conduite à tenir est de <strong>doser les transaminases et le temps de Quick (TP)</strong>. Si le TP est abaissé, il faut doser le <strong>facteur V</strong>.</p>"},{"i":"cbc08973fde5","n":278,"o":"278-14","u":"Identifier une urgence","t":"Connaître les situations d’urgence devant un ictère de l’adulte","q":"Comment doit-on évoquer et prendre en charge une angiocholite devant un ictère fébrile chez l'adulte ?","a":"<p>L'angiocholite doit être évoquée devant <strong>tout ictère fébrile</strong>. Elle impose la réalisation d'<strong>hémocultures</strong> en urgence.</p>"},{"i":"e2ee74cdaa31","n":278,"o":"278-14","u":"Identifier une urgence","t":"Connaître les situations d’urgence devant un ictère de l’adulte","q":"Quand faut-il adresser un patient en urgence à un centre de transplantation hépatique suite à l'exploration d'un ictère avec insuffisance hépatique ?","a":"<p>Un patient doit être adressé en urgence à un centre de transplantation hépatique si le <strong>facteur V est inférieur à 50 %</strong>, suggérant une insuffisance hépatique sévère.</p>"},{"i":"6f720071edf0","n":278,"o":"278-2","u":"Étiologies","t":"Connaître les situations urgentes devant un ictère du nouveau-né","q":"Qu'est-ce que l'ictère nucléaire chez le nouveau-né et quels sont ses principaux facteurs de risque ?","a":"<p>L'ictère nucléaire est une complication redoutée de l'hyperbilirubinémie néonatale, liée à la toxicité de la <strong>bilirubine libre</strong> sur le cerveau du nouveau-né, particulièrement vulnérable. Ses principaux facteurs de risque incluent :</p><ul><li>La <strong>prématurité</strong> et le <strong>jeûne</strong>.</li><li>Les <strong>médicaments déplacant la bilirubine de l'albumine</strong> (ex: aminosides).</li><li>La <strong>déshydratation</strong>, l'<strong>hypo-osmolarité</strong>, l'<strong>hypoalbuminémie</strong>.</li><li>L'<strong>infection</strong>, l'<strong>acidose</strong>, l'<strong>hypoxie</strong>, l'<strong>hypothermie</strong> et l'<strong>hypoglycémie</strong>.</li></ul>"},{"i":"755a7f3374ac","n":278,"o":"278-2","u":"Étiologies","t":"Connaître les situations urgentes devant un ictère du nouveau-né","q":"Quelles sont les séquelles neurologiques irréversibles de l'ictère nucléaire chez le nouveau-né ?","a":"<p>L'ictère nucléaire entraîne des séquelles neurologiques irréversibles par lésion des noyaux gris centraux et du tronc cérébral, incluant :</p><ul><li>Un <strong>syndrome extrapyramidal</strong>.</li><li>Une <strong>choréoathétose</strong>.</li><li>Une <strong>surdité de perception</strong>.</li><li>Une <strong>paralysie oculomotrice</strong>.</li><li>Un <strong>déficit intellectuel</strong>.</li></ul>"},{"i":"83f5edc35813","n":278,"o":"278-2","u":"Étiologies","t":"Connaître les situations urgentes devant un ictère du nouveau-né","q":"Quelles sont les trois situations urgentes principales à considérer devant un ictère néonatal ?","a":"<p>Les trois situations urgentes principales devant un ictère néonatal sont :</p><ul><li>L'<strong>ictère nucléaire</strong> (encéphalopathie hyperbilirubinémique).</li><li>L'<strong>atrésie des voies biliaires</strong>.</li><li>L'<strong>allo-immunisation érythrocytaire materno-fœtale</strong>.</li></ul>"},{"i":"8cfd48e7ccb8","n":278,"o":"278-2","u":"Étiologies","t":"Connaître les situations urgentes devant un ictère du nouveau-né","q":"Quelles sont les caractéristiques et l'urgence de l'atrésie des voies biliaires et de l'allo-immunisation érythrocytaire materno-fœtale comme cause d'ictère néonatal ?","a":"<ul><li>L'<strong>atrésie des voies biliaires</strong> se manifeste par un ictère à <strong>bilirubine conjuguée</strong>. La <strong>précocité de la chirurgie</strong> est cruciale et conditionne le pronostic vital.</li><li>L'<strong>allo-immunisation érythrocytaire materno-fœtale</strong> est un ictère à <strong>bilirubine libre</strong>, présentant un risque hémolytique important et constitue une urgence prise en charge au même titre que la cholestase.</li></ul>"},{"i":"2c8c31dd3857","n":278,"o":"278-3","u":"Diagnostic positif","t":"Connaître la stratégie diagnostique devant un ictère du nouveau-né","q":"Quelles sont les principales causes d'ictère néonatal à bilirubine libre ?","a":"<p>Les causes d'ictère néonatal à bilirubine libre sont :</p><ul><li><strong>Ictères bénins</strong> : ictère simple (physiologique), ictère au lait de mère.</li><li><strong>Hémolyse</strong> : allo-immunisations érythrocytaires materno-fœtales (ABO, Rhésus), hémolyses constitutionnelles (maladie de Minkowski-Chauffard, déficit en G6PD, déficit en pyruvate kinase).</li><li><strong>Sans hémolyse</strong> : infections materno-fœtales, hypothyroïdie, syndrome de Crigler-Najjar.</li></ul>"},{"i":"56edddb5670a","n":278,"o":"278-3","u":"Diagnostic positif","t":"Connaître la stratégie diagnostique devant un ictère du nouveau-né","q":"Quel est le dépistage systématique de l'ictère en maternité et quand une confirmation diagnostique est-elle indiquée ?","a":"<p>Le dépistage systématique se fait par <strong>bilirubinomètre transcutané (BTc)</strong> appliqué sur le front et le sternum, mesuré ≥ 1 fois par jour. La sortie est autorisée si la BTc reste &lt; 75ème percentile des courbes de référence.</p><p>Une confirmation diagnostique par dosage de la <strong>bilirubinémie totale et conjuguée</strong> est indiquée si :</p><ul><li>BTc <strong>≥ 75ème percentile</strong>.</li><li>Signes orientant vers un ictère pathologique.</li><li>Ictère persistant <strong>&gt; J7</strong> chez le nouveau-né à terme ou <strong>&gt; J14</strong> chez le prématuré.</li></ul>"},{"i":"ce36f6a06b61","n":278,"o":"278-3","u":"Diagnostic positif","t":"Connaître la stratégie diagnostique devant un ictère du nouveau-né","q":"Quelles sont les principales causes d'ictère néonatal à bilirubine conjuguée (choléstase) ?","a":"<p>Les causes d'ictère néonatal à bilirubine conjuguée sont :</p><ul><li><strong>Cholestase intra-hépatique</strong> : infections post-natales (<em>E. coli</em>), infections virales (CMV, EBV, échovirus).</li><li><strong>Cholestase extra-hépatique</strong> : <strong>atrésie des voies biliaires</strong>, autres anomalies des voies biliaires (l'absence de vésicule biliaire à l'échographie doit évoquer le diagnostic d'atrésie des voies biliaires).</li></ul>"},{"i":"d30ff15ed3f9","n":278,"o":"278-3","u":"Diagnostic positif","t":"Connaître la stratégie diagnostique devant un ictère du nouveau-né","q":"Quel bilan paraclinique est indiqué en cas d'ictère du nouveau-né, en fonction du type de bilirubine prédominante ?","a":"<p>Le bilan paraclinique est orienté :</p><ul><li><strong>Systématique</strong> (pour écarter une cause infectieuse) : <strong>CRP, hémocultures, ECBU</strong> (si ictère > J7), données bactériologiques maternelles.</li><li>Si <strong>bilirubine libre</strong> prédominante : <strong>NFS, réticulocytes, groupe sanguin enfant + mère, Coombs direct</strong>.</li><li>Si <strong>bilirubine conjuguée</strong> prédominante : <strong>bilan hépatique (PAL, γGT, transaminases, hémostase) + échographie abdominale</strong>.</li><li>Selon le contexte : <strong>G6PD, pyruvate kinase, TSH et T4</strong>.</li></ul><p>À noter que l'<strong>haptoglobine</strong> n'a aucun intérêt diagnostique chez le nouveau-né.</p>"},{"i":"ff93dfb6b848","n":278,"o":"278-3","u":"Diagnostic positif","t":"Connaître la stratégie diagnostique devant un ictère du nouveau-né","q":"Quels sont les critères qui doivent alerter et faire suspecter un ictère pathologique chez le nouveau-né ?","a":"<p>Devant un ictère du nouveau-né, doivent alerter :</p><ul><li>Un délai de survenue <strong>&lt; 24 heures de vie</strong>.</li><li>Une durée <strong>&gt; 10 jours</strong>.</li><li>Une intensité atteignant les <strong>plantes des pieds</strong>.</li><li>Un terrain particulier : âge gestationnel <strong>&lt; 38 SA</strong>, antécédents d'ictère traité dans la fratrie, incompatibilité ABO ou RAI maternelles positives, origine géographique Asie/Afrique/Antilles.</li><li>Des signes à l'examen : perte pondérale <strong>&gt; 8 %</strong>, signes d'<strong>hémolyse</strong> (anémie, hépato-splénomégalie) ou de <strong>cholestase</strong> (selles décolorées, urines foncées).</li></ul>"},{"i":"1342f27ad169","n":278,"o":"278-5","u":"Définition","t":"Connaître la définition d’un ictère de l’adulte","q":"Quelles sont les principales différences entre la bilirubine non-conjuguée et la bilirubine conjuguée concernant leur solubilité et leur présence dans les urines ?","a":"<ul><li>La <strong>bilirubine non-conjuguée</strong> est <strong>insoluble</strong>, majoritairement liée à l'albumine, et <strong>ne franchit pas la barrière glomérulaire</strong>, la rendant absente des urines.</li><li>La <strong>bilirubine conjuguée</strong> est <strong>soluble</strong> et passe librement le glomérule, ce qui fait qu'elle est retrouvée dans les urines.</li></ul>"},{"i":"6c336cf11a44","n":278,"o":"278-5","u":"Définition","t":"Connaître la définition d’un ictère de l’adulte","q":"À partir de quel seuil de bilirubinémie l'ictère devient-il cliniquement visible chez l'adulte ?","a":"<p>L'ictère devient cliniquement visible chez l'adulte lorsque la bilirubinémie totale atteint un seuil de <strong>> 40 à 50 µmol/L</strong>.</p>"},{"i":"a08deb56c248","n":278,"o":"278-5","u":"Définition","t":"Connaître la définition d’un ictère de l’adulte","q":"Quelle est la définition clinique d'un ictère chez l'adulte et à quelle anomalie biologique est-il secondaire ?","a":"<p>L'ictère de l'adulte se définit comme une coloration <strong>jaune à bronze généralisée</strong> des <strong>téguments</strong> et des <strong>conjonctives</strong>. Il est secondaire à une augmentation de la <strong>bilirubinémie</strong>, qu'elle soit conjuguée ou non conjuguée.</p>"},{"i":"bc07f90cf08e","n":278,"o":"278-5","u":"Définition","t":"Connaître la définition d’un ictère de l’adulte","q":"Comment qualifie-t-on un ictère selon le type de bilirubine prédominant ?","a":"<p>L'ictère est qualifié d'ictère à <strong>bilirubine non-conjuguée</strong> si celle-ci représente <strong>> 70 %</strong> de la bilirubinémie totale. Dans les autres cas, il est dit <strong>mixte</strong> ou à <strong>bilirubine conjuguée</strong>.</p>"},{"i":"5cefcccf4718","n":278,"o":"278-7","u":"Étiologies","t":"Connaître les principales étiologies de l’ictère de l’adulte","q":"Quelles sont les principales étiologies d'un ictère à bilirubine non-conjuguée chez l'adulte ?","a":"<p>Les principales étiologies d'un ictère à bilirubine non-conjuguée sont :</p><ul><li>Un <strong>excès de production</strong>, par <strong>hyperhémolyse</strong> (toutes causes d'hémolyse) ou <strong>dysérythropoïèse</strong>.</li><li>Un <strong>défaut de conjugaison</strong>, notamment le <strong>syndrome de Gilbert</strong> ou le <strong>syndrome de Crigler-Najjar</strong>.</li></ul>"},{"i":"6414a8cecfa9","n":278,"o":"278-7","u":"Étiologies","t":"Connaître les principales étiologies de l’ictère de l’adulte","q":"Quelles sont les principales étiologies d'un ictère à bilirubine conjuguée par cholestase avec obstacle sur les petits canaux biliaires chez l'adulte ?","a":"<p>Les principales étiologies d'un ictère à bilirubine conjuguée par cholestase avec obstacle sur les petits canaux biliaires sont :</p><ul><li>La <strong>cholangite biliaire primitive</strong> (avec anticorps anti-mitochondries M2).</li><li>La <strong>cholangite immuno-allergique</strong> (notamment médicamenteuse).</li><li>La <strong>cholangite sclérosante primitive</strong>.</li><li>La <strong>mucoviscidose</strong>.</li><li>Une <strong>mutation du transporteur canaliculaire MDR3</strong>.</li></ul>"},{"i":"a2ff7c4c237b","n":278,"o":"278-7","u":"Étiologies","t":"Connaître les principales étiologies de l’ictère de l’adulte","q":"Dans quelles situations peut-on observer un ictère à bilirubine mixte chez l'adulte ?","a":"<p>Un ictère à bilirubine mixte peut être observé en cas d'<strong>insuffisance hépatocellulaire grave</strong> (comme la <strong>cirrhose</strong> ou une <strong>hépatite aiguë</strong>) ou d'<strong>ictères de mécanismes multiples chez le malade en état grave</strong>.</p>"},{"i":"b3de4badc3d9","n":278,"o":"278-7","u":"Étiologies","t":"Connaître les principales étiologies de l’ictère de l’adulte","q":"Quelles sont les principales étiologies d'un ictère à bilirubine conjuguée par cholestase sans obstacle ou par atteinte du transport sans cholestase chez l'adulte ?","a":"<p>Les principales étiologies d'un ictère à bilirubine conjuguée sont :</p><ul><li>Les causes de <strong>cholestase sans obstacle</strong> :<ul><li><strong>Génétiques</strong> : cholestase intra-hépatique familiale progressive (PFIC), cholestase récurrente bénigne, cholestase gravidique.</li><li><strong>Acquises</strong> : hépatites aiguës, infections bactériennes sévères, angiocholite (par inhibition par cytokines pro-inflammatoires).</li></ul></li><li>Les causes d'<strong>atteinte du transport sans cholestase</strong> : <strong>syndrome de Rotor</strong>, <strong>maladie de Dubin-Johnson</strong>.</li></ul>"},{"i":"bab7522e7b61","n":278,"o":"278-7","u":"Étiologies","t":"Connaître les principales étiologies de l’ictère de l’adulte","q":"Quelles sont les principales étiologies d'un ictère à bilirubine conjuguée par cholestase avec obstacle sur la voie biliaire principale chez l'adulte ?","a":"<p>Les principales étiologies d'un ictère à bilirubine conjuguée par cholestase avec obstacle sur la voie biliaire principale sont :</p><ul><li>La <strong>lithiase de la VBP</strong> (voie biliaire principale).</li><li>Le <strong>cholangiocarcinome</strong>.</li><li>Le <strong>cancer de la tête du pancréas</strong>.</li><li>Une <strong>adénopathie comprimant la VBP</strong>.</li><li>Une <strong>sténose post-opératoire</strong>.</li><li>Une <strong>pancréatite chronique calcifiante</strong>.</li><li>Des <strong>métastases hépatiques</strong>.</li></ul>"},{"i":"f7abca5fdafa","n":278,"o":"278-7","u":"Étiologies","t":"Connaître les principales étiologies de l’ictère de l’adulte","q":"Quels sont les trois principaux mécanismes physiopathologiques responsables d'un ictère chez l'adulte ?","a":"<p>Les trois principaux mécanismes sont :</p><ul><li>Un excès de <strong>bilirubine non-conjuguée</strong> (libre).</li><li>Une atteinte de l'excrétion de la <strong>bilirubine conjuguée</strong> (directe) avec cholestase.</li><li>Une atteinte du transport de la <strong>bilirubine conjuguée</strong> sans cholestase, ou une atteinte mixte.</li></ul>"},{"i":"848b3579df3f","n":278,"o":"278-9","u":"Diagnostic positif","t":"Connaître les tableaux cliniques d’ictère selon l’étiologie","q":"Comment différencier un ictère vrai d'une fausse coloration jaune des téguments ?","a":"<p>Il est crucial de distinguer l'ictère vrai (élévation de la bilirubinémie) d'autres colorations jaunes :</p><ul><li>Les <strong>fausses colorations jaunes des téguments</strong> sont exceptionnelles et peuvent être dues à une alimentation riche en <strong>légumes rouges ou orangés</strong>, ou à l'ingestion de <strong>fluorescéine</strong> utilisée pour l'angiographie rétinienne.</li><li>Ces fausses colorations <strong>ne s'accompagnent pas d'une élévation de la bilirubinémie</strong> ni d'un ictère conjonctival. L'ictère vrai est caractérisé par la <strong>coloration jaune des conjonctives</strong>.</li></ul>"},{"i":"bc8888e76950","n":278,"o":"278-9","u":"Diagnostic positif","t":"Connaître les tableaux cliniques d’ictère selon l’étiologie","q":"Quels signes cliniques orientent spécifiquement vers l'étiologie d'un ictère cholestatique ?","a":"<p>Certains signes cliniques orientent spécifiquement vers un ictère cholestatique :</p><ul><li>Le <strong>prurit</strong> est toujours en faveur d'un ictère <strong>cholestatique</strong>.</li><li>Une <strong>grosse vésicule palpable</strong> oriente vers une obstruction cholédocienne <strong>néoplasique</strong> (notamment un cancer du pancréas).</li><li>Une <strong>douleur biliaire typique</strong> est fortement suggestive d'un ictère <strong>lithiasique</strong>.</li></ul>"},{"i":"cbac6dab2623","n":278,"o":"278-9","u":"Diagnostic positif","t":"Connaître les tableaux cliniques d’ictère selon l’étiologie","q":"Comment l'observation des urines et des selles permet-elle d'orienter le mécanisme d'un ictère ?","a":"<p>L'analyse clinique oriente vers le mécanisme :</p><ul><li>En cas d'ictère par <strong>bilirubine non-conjuguée</strong> : les urines sont <strong>claires</strong> (ou « coca-cola » si hémolyse intravasculaire) et les selles sont <strong>normales</strong>.</li><li>En cas d'ictère par <strong>bilirubine conjuguée</strong> : les urines sont <strong>foncées et brunes</strong>, et les selles sont <strong>décolorées</strong>.</li></ul>"}]};